'use strict';
globalThis.RaceMotion=class RaceMotion{
 constructor(){this.round=null;this.identity='';this.rows=new Map();this.ranks=new Map();this.events=[]}
 sample(r,now){const active=r.settings.running&&!r.settings.paused&&r.winner===null&&now>=r.startsAt,drivers=r.slots.slice(0,r.settings.cars).map((p,i)=>({p,i})).filter(x=>x.p),identity=JSON.stringify(drivers.map(x=>[x.i,x.p.id]));if(this.round!==r.round){this.round=r.round;this.rows.clear();this.ranks.clear();this.identity=''}const same=this.identity===identity;this.identity=identity;this.events=[];const ranking=[...drivers].sort((a,b)=>b.p.distance-a.p.distance||a.i-b.i),lead=ranking[0]?.p.distance||0,nextRanks=new Map();for(let rank=0;rank<ranking.length;rank++)nextRanks.set(ranking[rank].p.id,rank+1);
  for(const {p,i}of drivers){let row=this.rows.get(i);if(!row||row.id!==p.id||p.distance<row.distance){row={id:p.id,distance:p.distance,samples:[],boostUntil:active&&p.lastAssistAt&&now-p.lastAssistAt<1500?now+2200:0,lastAssist:p.lastAssistAt||0,pickups:0,progress:Math.floor(p.distance/(r.settings.step*4))};this.rows.set(i,row)}const delta=Math.max(0,p.distance-row.distance),assisted=(p.lastAssistAt||0)>row.lastAssist;row.samples=row.samples.filter(x=>now-x.at<3000);if(active&&delta>0)row.samples.push({at:now,distance:delta});if(active&&assisted)row.boostUntil=now+2200;const interval=Math.max(1,Math.min(3,(now-(row.samples[0]?.at??now))/1000+1));row.pace=active?row.samples.reduce((sum,x)=>sum+x.distance,0)/r.settings.step/interval:0;row.rank=nextRanks.get(p.id);row.gap=Math.max(0,lead-p.distance);const oldRank=this.ranks.get(p.id);if(active&&same&&delta>0&&oldRank&&row.rank<oldRank&&drivers.some(other=>this.ranks.get(other.p.id)<oldRank&&nextRanks.get(other.p.id)>row.rank&&other.p.distance<p.distance))this.events.push({type:'overtake',index:i,id:p.id,name:p.name,from:oldRank,to:row.rank,at:now});const progress=Math.floor(p.distance/(r.settings.step*4));if(active&&progress>row.progress){const count=progress-row.progress;row.pickups+=count;this.events.push({type:'pickup',index:i,count,total:row.pickups,at:now})}row.progress=progress;row.distance=p.distance;row.lastAssist=p.lastAssistAt||0;row.boosted=active&&now<row.boostUntil}
  for(const i of this.rows.keys())if(!drivers.some(x=>x.i===i))this.rows.delete(i);this.ranks=nextRanks;return {rows:this.rows,events:this.events,active}
 }
};
